<?php
/** Proof — JSON mode (spec "Proof", 6): every handler under a signed action token answers {ok, did, record_id, location}; _partial=1 keeps the client's fields; 422 {error: {code: invalid, fields}}; the agent's door. */
require __DIR__ . '/lib.php';
$beaTok = ['X-Action-Token: ' . person_token(28)];
$ownerTok = ['X-Action-Token: ' . person_token(1)];

echo "1. The handlers under a person's action token (no session, no CSRF)\n";
[$c, $b] = act_token('/clients/save.php', ['name' => 'SMOKE JSON Co', 'code' => 'json', 'email' => 'ap@json.invalid', 'terms_days' => '20', 'po_required' => 'yes', 'notes' => 'SMOKE note'], $beaTok);
$client = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $b['ok'] === true && $b['did'] === 'Added SMOKE JSON Co' && $client > 0 && $b['location'] === '/clients/' . $client . '?notice=saved' && $b['client_id'] === $client, 'client_save: {ok, did, record_id, location, client_id}');
[$c, $b] = act_token('/clients/save.php', ['client' => $client, 'name' => 'SMOKE JSON Co Ltd', '_partial' => '1'], $beaTok);
$row = q('SELECT name, code, email, terms_days, po_required, notes FROM clients WHERE id = :c', ['c' => $client])[0];
ok($c === 200 && $row['name'] === 'SMOKE JSON Co Ltd' && $row['code'] === 'JSON' && $row['email'] === 'ap@json.invalid' && (int) $row['terms_days'] === 20 && $row['po_required'] && $row['notes'] === 'SMOKE note', '_partial=1 with only the name: the code, email, terms, PO and notes kept from the base row');
[$c, $b] = act_token('/clients/save.php', ['client' => $client, 'name' => 'SMOKE JSON Co Ltd', 'po_required' => 'no'], $beaTok);
ok($c === 200 && !one('SELECT po_required FROM clients WHERE id = :c', ['c' => $client]) && (string) one('SELECT code FROM clients WHERE id = :c', ['c' => $client]) === 'JSON', 'without _partial, the handler\'s own "a field left out stays" still holds for text fields');
[$c, $b] = act_token('/clients/save.php', ['name' => '', 'code' => 'x'], $beaTok);
ok($c === 422 && ($b['error']['code'] ?? '') === 'invalid' && isset($b['error']['fields']['name'], $b['error']['fields']['code']) && is_array($b['error']['errors'] ?? null), 'a refusal: 422 {error: {code: invalid, fields, errors}}');
[$c, $b] = act_token('/clients/save.php', ['name' => 'SMOKE JSON Co Ltd'], $beaTok);
ok($c === 422 && ($b['error']['code'] ?? '') === 'invalid' && str_contains($b['error']['message'], 'already exists'), 'a refusal in words: 422 with the sentence');
[$c, $b] = act_token('/clients/contacts/save.php', ['client' => $client, 'name' => 'SMOKE Pat', 'email' => 'pat@json.invalid', 'receives_invoices' => 'yes'], $beaTok);
$contact = (int) $b['record_id'];
ok($c === 200 && $contact > 0 && $b['client_id'] === $client && $b['contact_id'] === $contact, 'client_contact_save: record_id, client_id, contact_id');
[$c, $b] = act_token('/clients/contacts/save.php', ['contact' => $contact, 'role' => 'CFO', '_partial' => '1'], $beaTok);
ok($c === 200 && q('SELECT role, email, receives_invoices FROM client_contacts WHERE id = :i', ['i' => $contact])[0] === ['role' => 'CFO', 'email' => 'pat@json.invalid', 'receives_invoices' => true], '_partial on a contact keeps the email and the flag');
[$c, $b] = act_token('/settings/rate-cards/save.php', ['name' => 'SMOKE JSON card', 'currency' => 'GBP'], $beaTok);
$card = (int) $b['record_id'];
[$c2, $b2] = act_token('/settings/rate-cards/rate.php', ['rate_card' => $card, 'role' => (int) one("SELECT id FROM consulting_roles WHERE key = 'consultant'"), 'bill_rate' => '150'], $beaTok);
ok($c === 200 && $card > 0 && $c2 === 200 && $b2['bill_rate'] === '150.00' && $b2['refresh'] === 'rateCardChanged', 'rate_card_save and rate_card_rate_save answer JSON (bill_rate, refresh)');
[$c, $b] = act_token('/settings/rate-cards/save.php', ['rate_card' => $card, 'effective_from' => '2026-06-01', '_partial' => '1'], $beaTok);
ok($c === 200 && q('SELECT name, currency, effective_from FROM rate_cards WHERE id = :c', ['c' => $card])[0] === ['name' => 'SMOKE JSON card', 'currency' => 'GBP', 'effective_from' => '2026-06-01'], '_partial on a card keeps the name and currency');
[$c, $b] = act_token('/settings/cost-rates/save.php', ['member' => 30, 'hourly_cost' => '60', 'valid_from' => '2026-01-01'], $ownerTok);
ok($c === 200 && ($b['record_id'] ?? 0) > 0 && $b['member_id'] === 30 && !isset($b['hourly_cost']), 'cost_rate_save (the admin): record_id and member_id, never the rate in the answer');
[$c, $b] = act_token('/settings/cost-rates/save.php', ['member' => 30, 'hourly_cost' => '60', 'valid_from' => '2026-01-01'], $beaTok);
ok($c === 403 && ($b['error']['code'] ?? '') === 'forbidden', 'Billing under a token: 403 forbidden');
[$c, $b] = act_token('/settings/roles/save.php', ['title' => 'SMOKE JSON role'], $ownerTok);
ok($c === 200 && ($b['record_id'] ?? 0) > 0 && $b['role_id'] === $b['record_id'], 'consulting_role_save: record_id (and role_id)');
[$c, $b] = act_token('/settings/roles/save.php', ['role' => $b['record_id'], 'sort_order' => '9', '_partial' => '1'], $ownerTok);
ok($c === 200 && (string) one('SELECT title FROM consulting_roles WHERE id = :i', ['i' => (int) $b['record_id']]) === 'SMOKE JSON role', '_partial on a role keeps the title');
[$c, $b] = act_token('/settings/general.php', ['receipt_threshold' => '50'], $ownerTok);
ok($c === 200 && $b['changed'] === ['receipt_threshold'] && $b['record_id'] === 1, 'settings_save answers the changed keys');
[$c, $b] = act_token('/settings/numbering.php', ['kind' => 'expense', 'padding' => '4'], $ownerTok);
ok($c === 200 && $b['kind'] === 'expense' && str_starts_with($b['preview'], 'EXP-'), 'numbering_save answers the kind and the preview');
[$c, $b] = act_token('/engagements/notes/save.php', ['record_type' => 'client', 'record' => $client, 'body' => 'SMOKE a JSON note'], $beaTok);
ok($c === 200 && ($b['record_id'] ?? 0) > 0 && $b['location'] === '/clients/' . $client . '?notice=noted#notes', 'note_add: record_id, lands on the record');
[$c, $b] = act_token('/engagements/notes/save.php', ['record_type' => 'ticket', 'record' => 1, 'body' => 'x'], $beaTok);
ok($c === 422 && isset($b['error']['fields']['record_type']), 'an unknown record type: 422 (field record_type)');
[$c, $b] = act_token('/clients/archive.php', ['client' => $client], $beaTok);
ok($c === 200 && $b['did'] === 'Archived SMOKE JSON Co Ltd' && $b['refresh'] === 'clientChanged', 'client_archive: did and refresh');
[$c, $b] = act_token('/clients/restore.php', ['client' => $client], $beaTok);
ok($c === 200 && $b['did'] === 'Restored SMOKE JSON Co Ltd', 'client_restore');
[$c, $b] = act_token('/clients/delete.php', ['client' => $client], $ownerTok);
ok($c === 200 && (int) one('SELECT count(*) FROM clients WHERE id = :c', ['c' => $client]) === 0, 'client_delete by the admin (the contact and the note go with it)');

echo "2. An agent's run token\n";
[$tok, $relay] = run_token(40, 901);
kernel_state(function ($s) { $s['facts']['901'] = ['valid' => true, 'is_agent' => true, 'member_id' => 40, 'run_id' => 901, 'request_id' => 'req-901', 'trigger' => 'duty', 'endpoints' => [['name' => 'Records MCP']]]; return $s; });
$since = last_activity_id();
[$c, $b] = act_token('/clients/save.php', ['name' => 'SMOKE By the Clerk', 'code' => 'CLERK'], ['X-Action-Token: ' . $tok, 'X-Action-Relay: ' . $relay]);
$byClerk = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $byClerk > 0, 'the Billing Clerk (billing role) adds a client under its run token');
$log = activity('client.create', $since);
ok(count($log) === 1 && $log[0]['source'] === 'agent' && (int) $log[0]['agent_run_id'] === 901 && $log[0]['request_id'] === 'req-901' && (int) $log[0]['actor_member_id'] === 40, 'its row is source agent, run 901, the kernel\'s request id, actor 40');
[$c, $b] = act_token('/clients/delete.php', ['client' => $byClerk], ['X-Action-Token: ' . $tok, 'X-Action-Relay: ' . $relay]);
ok($c === 403, 'the agent may not delete (the admin\'s): 403 — and for an admin agent the kernel would pause it as `deletion`');
[$c, $b] = act_token('/settings/cost-rates/save.php', ['member' => 26, 'hourly_cost' => '1', 'valid_from' => '2027-01-01'], ['X-Action-Token: ' . $tok, 'X-Action-Relay: ' . $relay]);
ok($c === 403, 'nor set a cost rate: 403');
$r = req('GET', '/clients/' . $byClerk, ['headers' => ['Accept: application/json', 'X-Action-Token: ' . $tok, 'X-Action-Relay: ' . $relay]]);
ok($r['code'] === 403, 'an agent does not open a person\'s screen: 403 (it reads through the MCP)');
kernel_state(function ($s) { unset($s['facts']); return $s; });
finish();
